import {projects, importedOn, diligence} from './data.js';
import {enableColumnResize} from './column-widths.js';
import {createContactsUI} from './contacts-ui.js';
const $=s=>document.querySelector(s);
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const key='wind-projects.workspace.v1';
let saved={},storageOK=true;
try{saved=JSON.parse(localStorage.getItem(key)||'{}');if(!saved||Array.isArray(saved)||typeof saved!=='object')saved={};}catch{saved={};storageOK=false;}
let current=null,tab='Overview',dragProject=null;
const tabs=['Overview','Project & Status','Partnership','Financials','Due Diligence','Evidence','History','Contacts','Research & Sources','Outreach'];
const note=p=>saved[p.id]||{};
const msg=t=>{$('#toast').textContent=t;$('#toast').style.display='block';clearTimeout(msg.timer);msg.timer=setTimeout(()=>$('#toast').style.display='none',4000);};
const contactDesk=createContactsUI({projects,notify:msg,onChanged:()=>{if(!current||['Contacts','Overview'].includes(tab))render();}});
function persist(){try{localStorage.setItem(key,JSON.stringify(saved));storageOK=true;return true;}catch{storageOK=false;msg('Browser storage unavailable. Export your notes before closing.');return false;}}
const pill=(t,color='')=>`<span class="pill ${color}">${esc(t)}</span>`;
const color=p=>p.signal==='Watchlist'?'':p.signal==='Reported process'?'amber':'green';
const signalLabel=signal=>({'Reported process':'Partnership opportunity reported','Sponsor invitation':'Sponsor seeking partners','Watchlist':'No confirmed invitation','Procurement':'Tender / RFQ announced'}[signal]||signal);
const verifiedMark=p=>{const count=contactDesk.verifiedCount(p);return count?`<span class="sidebar-verification" title="${count} verified email${count===1?'':'s'}" aria-label="${count} verified email${count===1?'':'s'}">${count>1?'✓✓':'✓'}</span>`:'';};
const opportunityTitle=p=>note(p).noOpportunity?'No current opportunity — counterparty reported no active opportunity at present':'Mark as no current opportunity';
const opportunityMark=p=>`<button class="opportunity-marker ${note(p).noOpportunity?'active':''}" data-no-opportunity="${p.id}" aria-label="${note(p).noOpportunity?'Remove no current opportunity mark from ':'Mark '}${esc(p.name)}" aria-pressed="${!!note(p).noOpportunity}" title="${esc(opportunityTitle(p))}">⊘</button>`;
const opportunityStatus=p=>`<span class="table-opportunity-status">${opportunityMark(p)}<span>${note(p).noOpportunity?'No current opportunity':'Availability unconfirmed'}</span></span>`;
const emailStatusTitle=p=>note(p).emailStatus==='responded'?'Response received':note(p).emailStatus==='sent'?'Email sent':'No outreach email recorded';
const emailStatusMark=p=>note(p).emailStatus?`<span class="email-status-dot ${note(p).emailStatus}" title="${emailStatusTitle(p)}" aria-label="${emailStatusTitle(p)}"></span>`:'';
function projectOrder(){const ids=projects.map(p=>p.id),stored=Array.isArray(saved.projectOrder)?saved.projectOrder:[];return [...stored.filter(id=>ids.includes(id)),...ids.filter(id=>!stored.includes(id))];}
function pipelineProjects(matches){const order=projectOrder(),position=new Map(order.map((id,index)=>[id,index])),sortGroup=items=>items.slice().sort((a,b)=>position.get(a.id)-position.get(b.id)),bottom=p=>!!note(p).noOpportunity||['Closed','Rejected'].includes(note(p).workflow),active=matches.filter(p=>!bottom(p));return sortGroup(active.filter(p=>!!note(p).priority)).concat(sortGroup(active.filter(p=>!note(p).priority)),sortGroup(matches.filter(bottom)));}
function orderedProjects(matches){return pipelineProjects(matches);}
function clarifySignalLabels(){
  document.querySelectorAll('.resizable-table tbody tr').forEach(row=>{
    const signal=row.children[4]?.querySelector('.pill');
    if(signal)signal.textContent=signalLabel(signal.textContent);
    const status=row.children[5];
    if(status&&!status.dataset.opportunityStatus)status.textContent='Not yet confirmed';
  });
  const legend=$('.status-legend');
  if(legend)legend.innerHTML='Sponsor seeking partners = sponsor invitation reported in prior research. Partnership opportunity reported = a media or intermediary source reported an investment or partnership opportunity. No confirmed invitation = no verified invitation found. Tender / RFQ announced = formal procurement route. Current availability must be confirmed separately.';
  document.querySelectorAll('.fact').forEach(fact=>{
    const label=fact.querySelector('label');
    const value=fact.querySelector('div');
    if(label?.textContent==='Signal classification'){label.textContent='Partnership Signal';if(value)value.textContent=signalLabel(value.textContent);}
  });
}
const link=(url,label)=>/^https:\/\//.test(url||'')?`<a href="${esc(url)}" target="_blank" rel="noopener noreferrer">${esc(label)}</a>`:esc(label);
const facts=entries=>`<div class="fact-grid">${entries.map(([k,v])=>`<div class="fact"><label>${esc(k)}</label><div>${esc(v)}</div></div>`).join('')}</div>`;
const list=items=>`<ul>${items.map(i=>`<li>${esc(i)}</li>`).join('')}</ul>`;
const card=(title,body,cls='')=>`<section class="card ${cls}"><h2>${esc(title)}</h2>${body}</section>`;
const metric=(label,value,sub)=>`<div class="metric"><span>${esc(label)}</span><strong>${esc(value)}</strong><small>${esc(sub)}</small></div>`;
const evidenceId=()=>`ev-${Date.now()}-${Math.random().toString(36).slice(2,8)}`;
const evidenceRecords=p=>[...(p.sources||[]).map((s,index)=>({id:`source-${index}`,title:s.title,type:'Imported research source',date:s.date,status:'Imported · not revalidated',url:s.url,notes:'Imported project reference. Recheck the source and record the current finding before relying on it.',readonly:true})),...(Array.isArray(note(p).evidence)?note(p).evidence:[])];
const evidenceForm=entry=>`<div class="evidence-form-grid"><label>Evidence title<input id="evidence-title" value="${esc(entry?.title||'')}" placeholder="e.g. Government approval record"></label><label>Evidence type<select id="evidence-type"><option ${entry?.type==='Official project source'?'selected':''}>Official project source</option><option ${entry?.type==='Government / regulatory'?'selected':''}>Government / regulatory</option><option ${entry?.type==='Commercial / offtake'?'selected':''}>Commercial / offtake</option><option ${entry?.type==='Ownership / corporate'?'selected':''}>Ownership / corporate</option><option ${entry?.type==='Media / market signal'?'selected':''}>Media / market signal</option><option ${entry?.type==='Other'?'selected':''}>Other</option></select></label><label>Date or period<input id="evidence-date" value="${esc(entry?.date||'')}" placeholder="YYYY-MM-DD or publication period"></label><label>Status<select id="evidence-status"><option ${entry?.status==='Confirmed'?'selected':''}>Confirmed</option><option ${entry?.status==='Reported · verify'?'selected':''}>Reported · verify</option><option ${entry?.status==='Contradicted'?'selected':''}>Contradicted</option><option ${entry?.status==='Pending review'?'selected':''}>Pending review</option></select></label><label class="evidence-url-field">Source URL<input id="evidence-url" type="url" value="${esc(entry?.url||'')}" placeholder="https://…"></label><label class="evidence-notes-field">What this supports<textarea id="evidence-notes" rows="4" placeholder="Record the claim supported, relevant entity, limitations and any conflict…">${esc(entry?.notes||'')}</textarea></label></div><input type="hidden" id="evidence-id" value="${esc(entry?.id||'')}"><p><button class="primary" id="save-evidence">${entry?'Update evidence':'Save evidence'}</button>${entry?'<button id="cancel-evidence">Cancel</button>':''}</p>`;
function evidenceEntry(item){const tone=item.status==='Confirmed'?'green':item.status==='Contradicted'?'red':'amber';return `<article class="evidence-entry"><div class="evidence-entry-head"><div><span class="pill">${esc(item.type||'Evidence')}</span> <span class="pill ${tone}">${esc(item.status||'Pending review')}</span><h3>${esc(item.title)}</h3></div>${item.readonly?'':`<div class="evidence-entry-actions"><button data-edit-evidence="${esc(item.id)}">Edit</button><button data-remove-evidence="${esc(item.id)}" class="danger-button">Remove</button></div>`}</div><div class="evidence-meta">${esc(item.date||'Date not recorded')} ${item.url?' · '+link(item.url,'Open source ↗'):''}</div><p>${esc(item.notes||'No supporting note recorded.')}</p></article>`;}
function evidenceSection(p){const records=evidenceRecords(p);return card('Evidence register',`<p class="muted">Keep project facts, ownership, approvals, commercial signals and supporting links here. Imported sources are read-only; added evidence is saved in this browser for this project.</p>${records.length?'<div class="evidence-list">'+records.map(evidenceEntry).join('')+'</div>':'<div class="empty">No evidence has been added yet.</div>'}`,'evidence-register')+card('Add project evidence',evidenceForm(null),'evidence-editor');}
function configurePortfolioViewport(){
  document.body.classList.add('portfolio-view');
  const content=$('#content');
  const summary=document.createElement('details');
  summary.className='portfolio-summary';
  const toggle=document.createElement('summary');
  toggle.textContent='Portfolio summary & research notes · imported data, not live-verified';
  summary.appendChild(toggle);
  const info=document.createElement('div');
  info.className='portfolio-summary-content';
  for(const selector of ['.metrics','.notice','.status-legend'])info.appendChild(content.querySelector(selector));
  summary.appendChild(info);
  content.querySelector('.section-head').before(summary);
}
function filtered(){const q=$('#search').value.toLowerCase();return pipelineProjects(projects.filter(p=>(!$('#country').value||p.country===$('#country').value)&&(!$('#signal').value||p.signal===$('#signal').value)&&`${p.name} ${p.developer} ${p.country}`.toLowerCase().includes(q)));}
function sidebar(){const rows=orderedProjects(filtered());$('#projects').innerHTML=rows.length?rows.map(p=>`<div class="project-item ${note(p).priority?'starred':''}" draggable="true" data-drag-project="${p.id}"><span class="project-drag-handle" title="Drag to reorder" aria-hidden="true">⠿</span><button class="project-link ${current===p.id?'active':''}" data-project="${p.id}" ${current===p.id?'aria-current="page"':''}>${esc(p.name)}<small>${esc(p.country)} · ${esc(p.developer)}</small></button>${emailStatusMark(p)}${verifiedMark(p)}${opportunityMark(p)}<button class="project-star" data-star="${p.id}" aria-label="${note(p).priority?'Remove '+esc(p.name)+' from starred projects':'Star '+esc(p.name)+' and keep it at the top'}" aria-pressed="${!!note(p).priority}" title="${note(p).priority?'Unstar project':'Star project'}">${note(p).priority?'★':'☆'}</button></div>`).join(''):'<div class="empty">No projects match these filters.</div>';$('#total').textContent=projects.length;}
function navigate(id,newTab='Overview'){current=projects.some(p=>p.id===id)?id:null;tab=tabs.includes(newTab)?newTab:'Overview';history.replaceState(null,'',current?`#${current}/${encodeURIComponent(tab)}`:'#portfolio');render();window.scrollTo({top:0});}
function portfolio(){const rows=filtered();$('#breadcrumb').textContent='Portfolio overview';$('#content').innerHTML=`<div class="heading"><div><div class="eyebrow">GLOBAL WIND · RESEARCH WORKSPACE</div><h1>Opportunity starts with clarity.</h1><p class="intro">One place to review projects, understand partnership signals and turn unanswered questions into the next conversation.</p></div><span class="pill">LOCAL EDITION / 01</span></div><div class="metrics">${metric('Projects in library',projects.length,'Individual assets + portfolios')}${metric('Countries',new Set(projects.map(p=>p.country)).size,'Global opportunity coverage')}${metric('Prioritised',projects.filter(p=>note(p).priority).length,'Your manually starred projects')}${metric('Deliverable mailboxes',contactDesk.verifiedCount(),'Reoon positive · identity separate')}</div><div class="notice">Imported research leads · ${importedOn}. Sources and availability have not been rechecked in this build. A reported process is not a confirmed open opportunity. Missing information stays unknown.</div><div class="section-head"><h2>Project pipeline</h2><small>${rows.length} of ${projects.length} projects · filter from the sidebar</small></div><div class="table-wrap"><table><thead><tr><th>Project</th><th>Developer</th><th>Country</th><th>Reported scale</th><th>Partnership Signal</th><th>Opportunity Status</th><th>Your workflow</th><th>Review</th></tr></thead><tbody>${rows.map(p=>`<tr><td><span class="table-project-name"><button class="table-star project-star" data-star="${p.id}" aria-label="${note(p).priority?'Unstar':'Star'} ${esc(p.name)}" aria-pressed="${!!note(p).priority}">${note(p).priority?'★':'☆'}</button><button class="text-button" data-project="${p.id}">${esc(p.name)}</button></span></td><td>${esc(p.developer)}</td><td>${esc(p.country)}</td><td>${esc(p.capacity)}</td><td>${pill(p.signal,color(p))}</td><td data-opportunity-status="${p.id}">${opportunityStatus(p)}</td><td>${pill(note(p).workflow||'Not contacted')}<small>${note(p).followup?`Follow-up: ${esc(note(p).followup)}`:'No follow-up set'}</small></td><td><button class="quiet" data-project="${p.id}" aria-label="Open ${esc(p.name)}">Open ↗</button></td></tr>`).join('')}</tbody></table>${rows.length?'':'<div class="empty">No matching projects. Clear the sidebar filters.</div>'}</div><p class="status-legend">Sponsor invitation = invitation reported in prior research. Reported process = media or intermediary signal. Watchlist = no verified invitation. Procurement = formal tender route. ⊘ No current opportunity = counterparty reported no active opportunity at present.<br>Project scales are not aggregated: portfolios, batteries and wind capacity use different units and may overlap.</p>`;configurePortfolioViewport();enableColumnResize($('#content table'), $('#content .section-head'), msg);}
function header(p){return `<div class="heading"><div><div class="eyebrow">${esc(p.country)} / WIND OPPORTUNITY</div><h1><button class="detail-star project-star" data-star="${p.id}" aria-label="${note(p).priority?'Unstar':'Star'} ${esc(p.name)}" aria-pressed="${!!note(p).priority}" title="${note(p).priority?'Unstar project':'Star project'}">${note(p).priority?'★':'☆'}</button>${opportunityMark(p)}${esc(p.name)}</h1><p class="intro">${esc(p.developer)} <span class="slash">/</span> ${esc(p.capacity)}</p><div class="summary-line">${pill(p.signal,color(p))} &nbsp; ${note(p).noOpportunity?'<span class="opportunity-summary">No current opportunity</span> · ':''}Research imported ${importedOn} · live verification pending</div></div><div class="heading-actions"><button id="star" aria-pressed="${!!note(p).priority}">${note(p).priority?'★ Prioritised':'☆ Prioritise'}</button><button class="opportunity-action" data-no-opportunity="${p.id}" aria-pressed="${!!note(p).noOpportunity}">${note(p).noOpportunity?'⊘ No current opportunity':'⊘ Mark no current opportunity'}</button><button id="export-project">Export project</button></div></div><div class="tabs" role="tablist" aria-label="Project sections">${tabs.map(t=>`<button role="tab" id="tab-${tabs.indexOf(t)}" aria-selected="${t===tab}" aria-controls="panel" tabindex="${t===tab?0:-1}" class="tab ${t===tab?'selected':''}" data-tab="${esc(t)}">${esc(t)}</button>`).join('')}</div>`;}
function overview(p){return `<div class="two-col"><div>${card('Investment snapshot',`<p>${esc(p.summary)}</p>${facts([['Development status',p.stage],['Partnership availability',p.partnership],['Evidence level','Imported reference · not revalidated'],['Research completeness',p.id==='berwick-b'||p.id==='nose-hill'?'Expanded brief · diligence outstanding':'Initial brief · further research required']])}`)}${card('What needs to be established',list(p.gaps))}</div><div>${card('Recommended next step',`<p>${esc(p.next)}</p><button class="primary" data-tab="Outreach">Prepare an enquiry →</button>`,'action-card')}${card('Research discipline',`<p>No opportunity is classified as currently open without a dated confirmation. No unpublished financial terms are inferred.</p><p class="muted">Contacts: ${contactDesk.contacts(p).length} recorded · ${contactDesk.verifiedCount(p)} deliverable mailboxes<br>Diligence questions reviewed: ${diligence.filter(([k])=>note(p).checks?.[k]).length} / ${diligence.length}</p><button data-tab="Due Diligence">Review checklist</button>`)}</div></div>`;}
function draft(p){return `Subject: ${p.name} — Strategic Investment and Partnership\n\nDear ${p.id==='berwick-b'?'Berwick Bank team':p.id==='nose-hill'?'Ms. Beckie':'Project Team'},\n\nI am advising an established wind-energy developer on selected international opportunities for equity investment, joint ventures and strategic participation.\n\nI am contacting you regarding ${p.name} and would appreciate a brief, non-confidential overview of the project’s current development stage, ownership structure, capital requirements and available partnership opportunities.\n\nFor your review, please find below a brief profile of the developer:\n\nOur partner is a renewable-energy developer with experience in utility-scale wind and hybrid projects, covering development, engineering, construction, grid integration, commissioning and operations. Its wider group has pursued technology partnerships, international development frameworks and acquisitions of operating wind and hydrogen assets. It is currently evaluating equity investments, joint ventures and strategic participation in suitable projects.\n\nPlease direct me to the appropriate person responsible for the project’s partner process.\n\nKind regards,\n[Your name]\n[Company / contact details]`;}
function section(p){switch(tab){
case 'Overview':return overview(p);
case 'Project & Status':return card('Project facts',facts([['Project',p.name],['Country / location',p.location||p.country+' — exact location to confirm'],['Developer / sponsor',p.developer],['Reported capacity',p.capacity],['Technology',p.technology||'Wind; configuration and approved layout to verify'],['Development status',p.stage],['Permits / land','Supporting documents not reviewed'],['Grid connection','Connection agreement not reviewed'],['Commercial operation','No confirmed COD recorded'],['Last live verification','Not performed in this build']]))+card('Evidence gaps',list(p.gaps));
case 'Partnership':return `<div class="two-col"><div>${card('Opportunity & transaction perimeter',`<p>${esc(p.summary)}</p>${facts([['Signal classification',p.signal],['Current availability',p.partnership],['Participation route',p.signal==='Procurement'?'Formal procurement / eligibility requirements':p.signal==='Watchlist'?'Exploratory only; no confirmed invitation':'Equity / JV scope to confirm'],['Technology alliance','No specific alliance mandate established'],['Stake / governance','Not confirmed; request transaction terms'],['Deadlines / eligibility','Not verified; obtain current process instructions']])}`)}</div><div>${card('Before requesting confidential details',list(['Confirm sponsor or adviser authority.','Request a short non-confidential overview.','Agree a mutual NDA before document exchange.','Clarify investment ticket, stake and decision timetable.']),'action-card')}</div></div>`;
case 'Financials':return card('Financial evidence',`<p class="muted">Reported amounts are imported claims, not investment advice or verified financial models. Undisclosed values are not zero.</p>${facts([...(p.financials.length?p.financials:[['Capital expenditure','Not established'],['Capital requirement','Not established']]),['Equity valuation / purchase price','Not established'],['IRR / returns','No supported return forecast'],['Financial model','Not received or reviewed']])}`)+card('Information to request',list(['Base-case model and assumptions, including wind yield and curtailment.','Capex, contingency, construction schedule and currency exposure.','Executed revenue contracts and financing commitments.','Equity ticket, governance, dilution and exit scenarios.']));
case 'Due Diligence':return card('Due-diligence review checklist',`<p class="muted">Ticking a question records that you have reviewed it. It does not certify that the project passed diligence. Record findings and evidence in your notes.</p>${diligence.map(([k,t,d])=>`<label class="check-row"><input type="checkbox" data-check="${k}" ${note(p).checks?.[k]?'checked':''}><span><strong>${esc(t)}</strong><small>${esc(d)}</small></span></label>`).join('')}<label for="diligence-notes"><h3>Findings & evidence gaps</h3></label><textarea id="diligence-notes" placeholder="Record documents reviewed, source links, findings and open questions…">${esc(note(p).diligenceNotes||'')}</textarea><p><button class="primary" id="save-diligence">Save review notes</button></p>`);
case 'Evidence':return evidenceSection(p);
case 'History':return card('Project history & future milestones',`<p class="muted">Dates below are imported research. Targets are not achieved milestones.</p><div class="timeline">${p.history.map(([d,t])=>`<div class="event"><small>${esc(d)}</small><p>${esc(t)}</p></div>`).join('')}<div class="event"><small>${importedOn} · workspace event</small><p>Record imported into the standalone research desk. This is not a new project announcement or live verification.</p></div></div>`);
case 'Contacts':return contactDesk.view(p);
case 'Research & Sources':return card('Research brief',`<p>${esc(p.summary)}</p><p class="muted">This is a structured consolidation of available earlier research, not a newly completed deep-research report. Source content, dates, current job titles and project availability must be rechecked.</p>${list(p.gaps)}`)+card('Source register',p.sources.map(s=>`<div class="source">${link(s.url,s.title+' ↗')}<small>${esc(s.date)} · imported ${importedOn} · not revalidated</small><small>${esc(s.url)}</small></div>`).join(''))+card('Additional research notes',`<label class="sr-only" for="research-notes">Additional research notes</label><textarea id="research-notes" placeholder="Add dated research, citations and conflicting information…">${esc(note(p).researchNotes||'')}</textarea><p><button class="primary" id="save-research">Save research notes</button></p>`);
case 'Outreach':return `<div class="two-col"><div>${card('Draft an introductory enquiry',`<p class="muted">Editable draft only. Nothing is sent from this app.</p><label class="sr-only" for="draft">Email draft</label><textarea id="draft" rows="15">${esc(note(p).draft??draft(p))}</textarea><p><button class="primary" id="save-draft">Save draft</button> <button id="copy-draft">Copy draft</button></p>`)}</div><div>${card('Your relationship workflow',`<div class="form-row"><label>Stage<select id="workflow">${['Not contacted','Draft prepared','Contacted','Awaiting reply','NDA discussion','Under review','On hold','Closed'].map(v=>`<option ${note(p).workflow===v?'selected':''}>${v}</option>`).join('')}</select></label><label>Follow-up date<input type="date" id="followup" value="${esc(note(p).followup||'')}"></label></div><label>Email status<select id="email-status"><option value="" ${!note(p).emailStatus?'selected':''}>Not sent</option><option value="sent" ${note(p).emailStatus==='sent'?'selected':''}>Email sent</option><option value="responded" ${note(p).emailStatus==='responded'?'selected':''}>Response received</option></select></label><p class="outreach-status-help"><span class="email-status-dot sent"></span> Email sent &nbsp; <span class="email-status-dot responded"></span> Response received</p><label for="outreach-notes">Conversation notes</label><textarea id="outreach-notes" placeholder="Log your actual correspondence and next actions…">${esc(note(p).outreachNotes||'')}</textarea><p><button class="primary" id="save-outreach">Save workflow</button></p><p class="muted">Dates and outreach status are reminders in this workspace only. No email sending or scheduled notifications.</p>`)}${card('Storage',`<p class="muted">Notes, priorities and drafts are stored in this browser on this localhost origin. Use Export workspace to keep a portable backup. They do not sync to other browsers or services.</p>`)}</div></div>`;
}}
function render(){document.body.classList.remove('portfolio-view');sidebar();if(!current)return portfolio();const p=projects.find(p=>p.id===current);$('#breadcrumb').textContent=p.name;$('#content').innerHTML=header(p)+`<div id="panel" role="tabpanel" aria-labelledby="tab-${tabs.indexOf(tab)}">${section(p)}</div>`;}
function patch(values){saved[current]={...saved[current],...values};return persist();}
function download(name,payload){const a=document.createElement('a'),url=URL.createObjectURL(new Blob([JSON.stringify(payload,null,2)],{type:'application/json'}));a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
document.addEventListener('click',async e=>{
const star=e.target.closest('[data-star]');if(star){const id=star.dataset.star;const p=projects.find(item=>item.id===id);if(p){saved[id]={...saved[id],priority:!note(p).priority};if(persist()){sidebar();if(!current)portfolio();else render();msg(note(p).priority?'Project starred and moved to the top.':'Project unstarred.');}}return;}
const noOpportunity=e.target.closest('[data-no-opportunity]');if(noOpportunity){const id=noOpportunity.dataset.noOpportunity;const p=projects.find(item=>item.id===id);if(p){saved[id]={...saved[id],noOpportunity:!note(p).noOpportunity};if(persist()){sidebar();if(!current)portfolio();else render();msg(note(p).noOpportunity?'Marked as no current opportunity.':'No current opportunity mark removed.');}}return;}
const project=e.target.closest('[data-project]');if(project)return navigate(project.dataset.project);
const sectionButton=e.target.closest('[data-tab]');if(sectionButton){navigate(current,sectionButton.dataset.tab);$(`#tab-${tabs.indexOf(tab)}`)?.focus();return;}
const id=e.target.closest('button')?.id;
if(id==='portfolio-button')return navigate(null);
if(id==='export')return download('wind-projects-workspace.json',{schemaVersion:1,exportedAt:new Date().toISOString(),projects,contacts:contactDesk.snapshot(),notes:saved});
if(id==='import')return $('#import-file').click();
if(!current)return;
const p=projects.find(p=>p.id===current);
if(id==='star'){patch({priority:!note(p).priority});render();}
if(id==='export-project')download(p.id+'.json',{schemaVersion:1,exportedAt:new Date().toISOString(),project:p,contacts:contactDesk.contacts(p),verification:contactDesk.snapshot().checks,notes:{[p.id]:note(p)}});
if(id==='save-diligence'&&patch({diligenceNotes:$('#diligence-notes').value}))msg('Review notes saved in this browser.');
if(id==='save-research'&&patch({researchNotes:$('#research-notes').value}))msg('Research notes saved in this browser.');
if(id==='save-evidence'){
 const title=$('#evidence-title').value.trim(),url=$('#evidence-url').value.trim(),existingId=$('#evidence-id').value;
 if(!title){msg('Add an evidence title before saving.');return;}
 if(url&&!/^https:\/\//i.test(url)){msg('Source URL must begin with https://.');return;}
 const entry={id:existingId||evidenceId(),title,type:$('#evidence-type').value,date:$('#evidence-date').value.trim(),status:$('#evidence-status').value,url,notes:$('#evidence-notes').value.trim()};
 const records=Array.isArray(note(p).evidence)?note(p).evidence.slice():[];const index=records.findIndex(item=>item.id===entry.id);if(index>=0)records[index]=entry;else records.push(entry);
 if(patch({evidence:records})){render();msg(index>=0?'Evidence updated.':'Evidence saved in this browser.');}return;
}
if(id==='cancel-evidence'){render();return;}
if(id==='save-draft'&&patch({draft:$('#draft').value}))msg('Draft saved. Nothing has been sent.');
if(id==='copy-draft'){try{await navigator.clipboard.writeText($('#draft').value);msg('Draft copied. Nothing has been sent.');}catch{msg('Select the draft text and copy it manually.');}}
if(id==='save-outreach'){if(patch({workflow:$('#workflow').value,followup:$('#followup').value,emailStatus:$('#email-status').value,outreachNotes:$('#outreach-notes').value}))msg('Workflow and email status saved in this browser.');}
const editEvidence=e.target.closest('[data-edit-evidence]');if(editEvidence&&current){const entry=(note(p).evidence||[]).find(item=>item.id===editEvidence.dataset.editEvidence);if(entry){document.querySelector('.evidence-editor')?.scrollIntoView({behavior:'smooth',block:'start'});document.querySelector('.evidence-editor').innerHTML=`<h2>Edit project evidence</h2>${evidenceForm(entry)}`;}return;}
const removeEvidence=e.target.closest('[data-remove-evidence]');if(removeEvidence&&current){const idToRemove=removeEvidence.dataset.removeEvidence;if(confirm('Remove this evidence entry from the project?')){const records=(note(p).evidence||[]).filter(item=>item.id!==idToRemove);if(patch({evidence:records})){render();msg('Evidence removed from this browser.');}}return;}
});
document.addEventListener('dragstart',e=>{const item=e.target.closest('[data-drag-project]');if(!item)return;dragProject=item.dataset.dragProject;item.classList.add('dragging');e.dataTransfer.effectAllowed='move';e.dataTransfer.setData('text/plain',dragProject);});
document.addEventListener('dragover',e=>{const item=e.target.closest('[data-drag-project]');if(!item||!dragProject)return;e.preventDefault();document.querySelectorAll('.project-item.drag-over').forEach(el=>el.classList.remove('drag-over'));if(item.dataset.dragProject!==dragProject)item.classList.add('drag-over');});
document.addEventListener('drop',e=>{const target=e.target.closest('[data-drag-project]');if(!target||!dragProject)return;e.preventDefault();const targetId=target.dataset.dragProject,from=projects.find(p=>p.id===dragProject),to=projects.find(p=>p.id===targetId);if(!from||!to||from.id===to.id)return;const fromNoOpportunity=!!note(from).noOpportunity,toNoOpportunity=!!note(to).noOpportunity;if(fromNoOpportunity!==toNoOpportunity){msg('No current opportunity projects stay at the bottom. Reorder within each group.');return;}if(!fromNoOpportunity&&!!note(from).priority!==!!note(to).priority){msg('Starred projects stay above unstarred projects. Reorder within each group.');return;}const ids=projectOrder().filter(id=>id!==dragProject);const targetIndex=ids.indexOf(targetId);ids.splice(targetIndex<0?ids.length:targetIndex,0,dragProject);saved.projectOrder=ids;if(persist()){sidebar();if(!current)portfolio();msg('Project order saved.');}});
document.addEventListener('dragend',()=>{dragProject=null;document.querySelectorAll('.project-item.dragging,.project-item.drag-over').forEach(el=>el.classList.remove('dragging','drag-over'));});
document.addEventListener('change',e=>{if(e.target.matches('[data-check]'))patch({checks:{...saved[current]?.checks,[e.target.dataset.check]:e.target.checked}});if(e.target.id==='email-status'&&current){const value=e.target.value;if(patch({emailStatus:value})){sidebar();msg(value==='responded'?'Response received status saved.':value==='sent'?'Email sent status saved.':'Email status cleared.');}}});
document.addEventListener('keydown',e=>{if(e.target.matches('[role="tab"]')&&['ArrowRight','ArrowLeft','Home','End'].includes(e.key)){e.preventDefault();const i=tabs.indexOf(tab);const next=e.key==='Home'?0:e.key==='End'?tabs.length-1:(i+(e.key==='ArrowRight'?1:-1)+tabs.length)%tabs.length;navigate(current,tabs[next]);$(`#tab-${next}`).focus();}});
$('#import-file').addEventListener('change',async e=>{const f=e.target.files[0];if(!f)return;try{if(f.size>5000000)throw Error('File too large (5 MB maximum).');const data=JSON.parse(await f.text());if(data.schemaVersion!==1||!data.notes||typeof data.notes!=='object'||Array.isArray(data.notes))throw Error('Not a supported workspace export.');if(!confirm('Merge imported notes? Matching project notes will be replaced. Export your current workspace first if needed.'))return;for(const p of projects){const n=data.notes[p.id];if(!n||typeof n!=='object'||Array.isArray(n))continue;const clean={priority:n.priority===true,noOpportunity:n.noOpportunity===true,emailStatus:['sent','responded'].includes(n.emailStatus)?n.emailStatus:''};for(const k of ['diligenceNotes','researchNotes','draft','workflow','followup','outreachNotes'])if(typeof n[k]==='string')clean[k]=n[k].slice(0,100000);clean.checks={};for(const [k] of diligence)clean.checks[k]=n.checks?.[k]===true;saved[p.id]=clean;}if(persist())msg('Notes imported. Research records were not overwritten.');render();}catch(err){msg('Import failed: '+err.message);}finally{e.target.value='';}});
for(const country of [...new Set(projects.map(p=>p.country))].sort())$('#country').insertAdjacentHTML('beforeend',`<option>${esc(country)}</option>`);
const signalCopy={'Reported process':'Partnership opportunity reported','Sponsor invitation':'Sponsor seeking partners','Watchlist':'No confirmed invitation','Procurement':'Tender / RFQ announced','Validation required':'Validation required','Sponsor claim':'Sponsor claim'};
for(const signal of [...new Set(projects.map(p=>p.signal).filter(Boolean))].sort())if(![...$('#signal').options].some(option=>option.value===signal))$('#signal').insertAdjacentHTML('beforeend',`<option>${esc(signal)}</option>`);
const signalCounts=projects.reduce((counts,p)=>{if(p.signal)counts[p.signal]=(counts[p.signal]||0)+1;return counts;},{});
for(const option of $('#signal').options){const value=option.value;const label=value?(signalCopy[value]||value):'All signals';option.value=value;option.textContent=`${label} (${value?signalCounts[value]||0:projects.length})`;}
for(const id of ['search','country','signal'])$('#'+id).addEventListener(id==='search'?'input':'change',()=>{sidebar();if(!current)portfolio();});
const baseRender=render;render=()=>{baseRender();clarifySignalLabels();};
function route(){const [id,t]=location.hash.slice(1).split('/');let decoded='Overview';try{decoded=decodeURIComponent(t||'Overview');}catch{}navigate(id,decoded);}
window.addEventListener('hashchange',route);route();if(!storageOK)msg('Browser storage could not be read. Export your work before closing.');
contactDesk.load();
